     where
         F: FnMut(PageAligned<VirtualAddress>, PageTableEntry) -> Result<(), Error>,
     {
         let mut user_page_table_iter = self.user_page_tables.iter();
         loop {
             let (pgtab_addr, page_table) = match user_page_table_iter.next() {
                 Some(entry) => entry,
                 None => break,
